WITH monthly_cc AS (SELECT cc.cc_call_center_sk AS cc_sk, cc.cc_name, d.d_year, d.d_month_seq, SUM(cr.cr_net_loss) AS catalog_monthly_net_loss, SUM(COALESCE(sr.sr_net_loss,0)) AS store_monthly_net_loss, SUM(cr.cr_net_loss) + SUM(COALESCE(sr.sr_net_loss,0)) AS monthly_net_loss FROM call_center cc JOIN catalog_returns cr ON cc.cc_call_center_sk = cr.cr_call_center_sk JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk LEFT JOIN store_returns sr ON sr.sr_returned_date_sk = d.d_date_sk WHERE d.d_year BETWEEN 2020 AND 2022 GROUP BY cc.cc_call_center_sk, cc.cc_name, d.d_year, d.d_month_seq), windowed_cc AS (SELECT cc_sk, cc_name, d_year, d_month_seq, monthly_net_loss, LAG(monthly_net_loss) OVER (PARTITION BY cc_sk ORDER BY d_year, d_month_seq) AS prev_month_loss, SUM(monthly_net_loss) OVER (PARTITION BY cc_sk ORDER BY d_year, d_month_seq ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS rolling_6m_loss, ROW_NUMBER() OVER (PARTITION BY cc_sk ORDER BY d_year DESC, d_month_seq DESC) AS rn FROM monthly_cc) SELECT cc_sk, cc_name, d_year, d_month_seq, monthly_net_loss, prev_month_loss, CASE WHEN prev_month_loss IS NULL OR prev_month_loss = 0 THEN NULL ELSE (monthly_net_loss - prev_month_loss) / prev_month_loss * 100 END AS growth_pct, rolling_6m_loss, CASE WHEN prev_month_loss IS NOT NULL AND prev_month_loss <> 0 AND (monthly_net_loss - prev_month_loss) / prev_month_loss * 100 > 20 THEN 'Rapid Increase' ELSE 'Stable' END AS growth_flag, DENSE_RANK() OVER (ORDER BY monthly_net_loss DESC) AS loss_rank_latest_month FROM windowed_cc WHERE rn = 1 ORDER BY loss_rank_latest_month LIMIT 10
